from storage_client import get_blob_service_client


def list_prefix(payload, config=None):
    config = config or {}
    account_url = config['account_url']
    container_name = config['container']
    prefix = payload.get('prefix', '')

    client = get_blob_service_client(account_url)
    container_client = client.get_container_client(container_name)

    blobs = []
    for blob in container_client.list_blobs(name_starts_with=prefix):
        blobs.append({
            'object_name': blob.name,
            'size': blob.size,
            'creation_time': blob.creation_time.isoformat(),
            'last_modified': blob.last_modified.isoformat(),
            'content_type': blob.content_settings.content_type,
        })

    return {'prefix': prefix, 'objects': blobs}

import os
from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def stored_document_ocr(payload, config=None):
    config = config or {}
    endpoint = config.get('vision_endpoint')
    key = config.get('vision_key')
    image_url = payload['image_url'] # This should be a public URL or a SAS URL to the blob

    if not endpoint or not key:
        raise ValueError("Azure AI Vision endpoint and key must be provided in config.")

    client = ImageAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    # Analyze a remote image
    result = client.analyze(
        image_url=image_url,
        visual_features=[VisualFeatures.READ],
        language="en", # Assuming English for simplicity
        gender_neutral_caption=True,
    )

    extracted_text = []
    if result.read and result.read.blocks:
        for block in result.read.blocks:
            for line in block.lines:
                extracted_text.append(line.text)

    return {'image_url': image_url, 'extracted_text': "\n".join(extracted_text)}

import os
from openai import AzureOpenAI


def stored_asset_summary(payload, config=None):
    config = config or {}
    azure_openai_endpoint = config.get('azure_openai_endpoint')
    azure_openai_key = config.get('azure_openai_key')
    azure_openai_deployment = config.get('azure_openai_deployment') # e.g., 'gpt-4-turbo'
    text_to_summarize = payload['text']

    if not all([azure_openai_endpoint, azure_openai_key, azure_openai_deployment]):
        raise ValueError("Azure OpenAI endpoint, key, and deployment must be provided in config.")

    client = AzureOpenAI(
        azure_endpoint=azure_openai_endpoint,
        api_key=azure_openai_key,
        api_version="2024-02-01", # Or other supported API version
    )

    try:
        response = client.chat.completions.create(
            model=azure_openai_deployment,
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes text."},
                {"role": "user", "content": f"Please summarize the following text:\n\n{text_to_summarize}"}
            ],
            max_tokens=200, # Adjust as needed for summary length
            temperature=0.7,
        )
        summary = response.choices[0].message.content.strip()
    except Exception as e:
        summary = f"Error summarizing text: {e}"

    return {'original_text_length': len(text_to_summarize), 'summary': summary}
